// Zweck: Frist und Puffer aus k1_einstellungen pruefen, Grenzzeit und decided_at berechnen, Filteradresse bauen.
const k = $('Konfiguration [Edit Fields]').first().json;
// fullResponse ist an: die Zeilen stehen in body
const zeilen = $input.first().json.body;
if (!Array.isArray(zeilen)) throw new Error('Einstellungen: Antwort ist keine Liste');
const hole = (schluessel) => { const z = zeilen.find(r => r && r.setting_key === schluessel); return z ? z.setting_value : undefined; };
// gleiche Regel wie im Freigabe-Sub und im Hauptworkflow: ganze Zahl von 1 bis 1440
const fristText = String(hole('freigabe_frist_minuten') ?? '');
if (!/^[1-9]\d{0,3}$/.test(fristText) || Number(fristText) > 1440) throw new Error('freigabe_frist_minuten ist keine ganze Zahl von 1 bis 1440');
// Puffer: ganze Zahl von 0 bis 120
const pufferText = String(hole('freigabe_puffer_minuten') ?? '');
if (!/^(0|[1-9]\d{0,2})$/.test(pufferText) || Number(pufferText) > 120) throw new Error('freigabe_puffer_minuten ist keine ganze Zahl von 0 bis 120');
// Meldeziel vor dem Markieren pruefen, sonst waeren Beitraege markiert und die Meldung haette kein Ziel
const chatText = String(hole('telegram_chat_id') ?? '').trim();
if (!/^-?\d{1,20}$/.test(chatText)) throw new Error('telegram_chat_id fehlt oder ist keine Zahl');
const frist = Number(fristText);
const puffer = Number(pufferText);
const jetzt = new Date();
// decided_at wird hier festgelegt, der PATCH und die Fehlerzeile tragen denselben Wert (Wiederfinden bei verlorener Antwort)
const decidedAt = jetzt.toISOString();
const grenze = new Date(jetzt.getTime() - (frist + puffer) * 60000).toISOString();
// eine Adresse fuer den Markier-PATCH und den Trockenlauf, UTC mit Z
const filterUrl = k.supabase_basis + '/k1_posts?status=eq.' + k.status_wartend + '&erzeugt_von=eq.' + k.erzeugt_von + '&created_at=lt.' + grenze;
return [{ json: { frist_minuten: frist, puffer_minuten: puffer, chat_id: chatText, grenzzeit: grenze, decided_at: decidedAt, filter_url: filterUrl, status_abgelaufen: k.status_abgelaufen } }];

// Zweck: alle markierten Beitraege zu 1 Sammelmeldung (HTML, Zeit in Berlin, hoechstens 3500 Zeichen).
const g = $('Grenzzeit berechnen [Code]').first().json;
const zeilen = $('Abgelaufene markieren [HTTP Request]').first().json.body;
if (!Array.isArray(zeilen) || zeilen.length === 0) throw new Error('PATCH-Antwort ist keine Liste mit Zeilen');
// Thema fuer parse_mode HTML entschaerfen
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const zeit = (iso) => { const d = new Date(iso); return isNaN(d.getTime()) ? 'unbekannt' : d.toLocaleString('de-DE', { timeZone: 'Europe/Berlin', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }); };
const n = zeilen.length;
const kopf = 'Keine Entscheidung bis zum Fristende, nicht veröffentlicht: ' + n + (n === 1 ? ' Beitrag.' : ' Beiträge.');
const grenze = 3500;
let text = kopf;
let gezeigt = 0;
for (const z of zeilen) {
  const zeile = '\n• ' + esc(z.topic || '(ohne Thema)') + ' (angelegt ' + zeit(z.created_at) + ')';
  // Platz fuer die Restzeile freihalten
  const reserve = ('\nund ' + n + ' weitere').length;
  if ((text + zeile).length + reserve > grenze) break;
  text += zeile;
  gezeigt++;
}
if (gezeigt < n) text += '\nund ' + (n - gezeigt) + ' weitere';
return [{ json: { text: text, chat_id: g.chat_id, anzahl: n, gezeigt: gezeigt } }];

// Zweck: je markiertem Beitrag 1 Zeile fuer k1_laufprotokoll (stage ende, status ok), ohne Thema.
const k = $('Konfiguration [Edit Fields]').first().json;
const zeilen = $('Abgelaufene markieren [HTTP Request]').first().json.body;
if (!Array.isArray(zeilen) || zeilen.length === 0) throw new Error('keine markierten Zeilen fuer das Protokoll');
const start = Date.parse(k.start_time);
const dauer = Number.isFinite(start) ? Math.max(0, Date.now() - start) : null;
// post_id ist in k1_laufprotokoll eine uuid
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const protokoll = zeilen.map(z => {
  if (!uuid.test(String(z.id))) throw new Error('Beitrag ohne gueltige id in der PATCH-Antwort');
  // trace_id ist die execution_id des Beitrags, execution_mode test bei manuellen Laeufen, production beim Zeitplan
  return { workflow_name: k.workflow_name, execution_id: String($execution.id), execution_mode: $execution.mode, stage: 'ende', status: 'ok', post_id: z.id, trace_id: z.execution_id == null ? null : String(z.execution_id), duration_ms: dauer };
});
return [{ json: { zeilen: protokoll } }];

// Zweck: jeden Fehlerausgang (und Versand belegt? Nein) in 1 Fehlerzeile fassen, ohne Thema und ohne Beitragstext.
// Die Kette ist linear: der Knoten, der als letzter lief, ist der, an dem es scheiterte.
const reihe = ['Einstellungen laden [HTTP Request]', 'Grenzzeit berechnen [Code]', 'Abgelaufene markieren [HTTP Request]', 'Beitrag abgelaufen? [If]', 'Meldung bauen [Code]', 'Frist melden [Telegram]', 'Versand belegt? [If]', 'Protokollzeilen bauen [Code]', 'Protokoll schreiben [HTTP Request]'];
// Kein stiller Fehlschlag: jeder gescheiterte Zugriff landet mit Grund in hinweise und in der Fehlerzeile.
const hinweise = [];
const lief = (name) => { try { return $(name).isExecuted === true; } catch (e) { hinweise.push(name + " isExecuted: " + String((e && e.message) || e)); return false; } };
let knoten = 'unbekannt';
for (const name of reihe) { if (lief(name)) knoten = name; }
const ein = ($input.first() && $input.first().json) ? $input.first().json : {};
let fehlerText = 'Fehler ohne Meldung';
if (ein.error) {
  const e = ein.error;
  fehlerText = typeof e === 'string' ? e : (e.message || e.description || JSON.stringify(e));
} else if (knoten === 'Versand belegt? [If]') {
  fehlerText = 'Telegram hat den Versand nicht bestaetigt (kein ok oder keine message_id)';
}
// decided_at nur, wenn Grenzzeit berechnen lief; damit sind markierte Zeilen auch ohne PATCH-Antwort auffindbar
const holeErstes = (name) => { const fehler = []; try { const e = $(name).first(); if (e && e.json) return { json: e.json, fehler }; fehler.push(name + ' first(): leer'); } catch (e) { fehler.push(name + ' first(): ' + String((e && e.message) || e)); } try { const a = $(name).all(0, 0); if (Array.isArray(a) && a[0] && a[0].json) return { json: a[0].json, fehler }; fehler.push(name + ' all(0,0): leer'); } catch (e) { fehler.push(name + ' all(0,0): ' + String((e && e.message) || e)); } return { json: null, fehler }; };
let decidedAt = '';
if (lief('Grenzzeit berechnen [Code]')) {
  const g = holeErstes('Grenzzeit berechnen [Code]');
  if (g.json && g.json.decided_at) decidedAt = String(g.json.decided_at);
  else hinweise.push('decided_at fehlt: ' + (g.fehler.join(' | ') || 'Feld leer'));
}
// Beitrags-IDs (je 8 Zeichen) nur, wenn der PATCH lief und eine Liste lieferte
let ids = [];
if (lief('Abgelaufene markieren [HTTP Request]')) {
  const p = holeErstes('Abgelaufene markieren [HTTP Request]');
  if (p.json && Array.isArray(p.json.body)) ids = p.json.body.map(z => String((z && z.id) || '').slice(0, 8));
  else if (p.json) hinweise.push('PATCH-Antwort ohne Liste');
  else hinweise.push('Beitrags-IDs fehlen: ' + p.fehler.join(' | '));
}
let start = NaN;
try { start = Date.parse($('Konfiguration [Edit Fields]').first().json.start_time); } catch (e) { start = NaN; hinweise.push('Startzeit fehlt: ' + String((e && e.message) || e)); }
let text = 'Knoten: ' + knoten + '; Fehler: ' + String(fehlerText).replace(/\s+/g, ' ').slice(0, 120);
if (decidedAt) text += '; decided_at: ' + decidedAt;
if (ids.length) text += '; Beitraege (' + ids.length + '): ' + ids.join(',');
if (hinweise.length) text += '; Zugriff: ' + hinweise.join('; ').replace(/\s+/g, ' ');
text = text.slice(0, 300);
const zeile = { workflow_name: 'AGT-2606 P2 Freigabe-Fristen', execution_id: String($execution.id), execution_mode: $execution.mode, stage: 'fehlerweg', status: 'fehler', error_text: text, duration_ms: Number.isFinite(start) ? Math.max(0, Date.now() - start) : null };
return [{ json: { knoten: knoten, decided_at: decidedAt || null, beitrag_ids: ids, hinweise: hinweise, zeile: zeile } }];
